import{_ as a,C as r,o as i,c as s,aj as e,G as n}from"./chunks/framework.BwH0p-pt.js";const A=JSON.parse('{"title":"Agentic PIM","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/agenticPim/index.md","filePath":"2.1/agenticPim/index.md","lastUpdated":1781078920000}'),d={name:"2.1/agenticPim/index.md"};function g(l,t,c,h,p,u){const o=r("ImagePopup");return i(),s("div",null,[t[0]||(t[0]=e('<h1 id="agentic-pim" tabindex="-1">Agentic PIM <a class="header-anchor" href="#agentic-pim" aria-label="Permalink to &quot;Agentic PIM&quot;">​</a></h1><blockquote><p><strong>Sidebar:</strong> <strong>Agentic PIM</strong><strong>Settings live at:</strong> Magic AI → Settings → <em>Agentic PIM</em> section (<code>/admin/configuration/general/magic_ai</code>)</p></blockquote><p><strong>Agentic PIM</strong> is UnoPim&#39;s flagship AI capability — the umbrella that covers every autonomous or semi-autonomous AI workflow the product runs on your behalf. From one settings card under <strong>Magic AI → Settings</strong>, you control:</p><ul><li>The <strong>AI Agent Chat</strong> panel (the floating star icon at the bottom-right of every admin page).</li><li>The <strong>Auto-Enrichment</strong> background job that fills missing product fields after creation.</li><li>The <strong>Catalog Quality Monitor</strong> scheduled scan.</li><li>The <strong>Confidence Threshold</strong> and <strong>Change Approval Mode</strong> that decide when AI-proposed changes reach your data vs. land in the Approval Queue.</li><li>The <strong>Daily Token Budget</strong> that caps combined spend across all of the above.</li></ul><h2 id="what-does-agentic-pim-do" tabindex="-1">What does Agentic PIM do? <a class="header-anchor" href="#what-does-agentic-pim-do" aria-label="Permalink to &quot;What does Agentic PIM do?&quot;">​</a></h2><p>Think of Agentic PIM as a small team of AI workers watching your catalog:</p><table tabindex="0"><thead><tr><th>Worker</th><th>Trigger</th><th>Outcome</th></tr></thead><tbody><tr><td><strong>AI Agent Chat</strong></td><td>You type an instruction in the chat panel.</td><td>Calls one or more of 30+ PIM tools to carry out your request.</td></tr><tr><td><strong>Auto-Enrichment</strong></td><td>A new product is created (manually or via import).</td><td>Fills in missing descriptions, SEO metadata, etc.</td></tr><tr><td><strong>Catalog Quality Monitor</strong></td><td>Scheduled (background).</td><td>Sweeps the catalog for thin or inconsistent data and surfaces it in Needs Attention.</td></tr><tr><td><strong>Approval Queue</strong></td><td>Any AI worker proposes a change.</td><td>Holds or applies the change based on your approval mode + confidence threshold.</td></tr></tbody></table><p>All four share the same Platform, Model, Prompt, System Prompt, and token budget — configured once from <strong>Magic AI → Settings</strong>.</p><h2 id="how-does-agentic-pim-work" tabindex="-1">How does Agentic PIM work? <a class="header-anchor" href="#how-does-agentic-pim-work" aria-label="Permalink to &quot;How does Agentic PIM work?&quot;">​</a></h2><p>Every Agentic PIM action follows the same five-step pipeline:</p>',10)),n(o,{src:"/assets/2.1/images/ai-agent/agentic-pim-pipeline.png",alt:"Agentic PIM Pipeline — 5-Step Workflow"}),t[1]||(t[1]=e('<p>This pipeline runs on top of the unified <strong>LaravelAiAdapter</strong>, so switching Platforms or Models under Magic AI Settings immediately changes every Agentic PIM worker&#39;s behaviour.</p><h2 id="configuration-—-the-agentic-pim-settings" tabindex="-1">Configuration — the Agentic PIM settings <a class="header-anchor" href="#configuration-—-the-agentic-pim-settings" aria-label="Permalink to &quot;Configuration — the Agentic PIM settings&quot;">​</a></h2><p>Open <strong>Magic AI → Settings</strong> and expand the <strong>Agentic PIM</strong> card. The fields are:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enable AI Agent Chat</strong></td><td>Master switch for the floating chat panel. When off, the star icon at the bottom-right is hidden and no user can converse with the agent. Auto-Enrichment and the Catalog Quality Monitor still run.</td></tr><tr><td><strong>Max Agent Steps Per Turn</strong></td><td>How many tool calls the agent may chain for a single trigger. Dropdown presets rather than raw numbers (e.g., <strong><code>3 (Fast)</code></strong>). Higher = more autonomy per turn; lower = tighter control and cheaper tokens.</td></tr><tr><td><strong>Daily Token Budget</strong></td><td>Global daily cap on tokens spent by Agentic PIM (e.g., <code>500000</code>). Shared across chat, enrichment, and monitoring. When the cap is hit, every AI worker pauses until the next day.</td></tr><tr><td><strong>Auto-Enrichment on Product Create</strong></td><td>When enabled, every newly created product is queued for background enrichment — missing descriptions, SEO fields, etc. are filled in automatically.</td></tr><tr><td><strong>Catalog Quality Monitor</strong></td><td>Runs a scheduled AI sweep that reports thin, missing, or inconsistent catalog data into the Dashboard&#39;s <strong>Needs Attention</strong> section.</td></tr><tr><td><strong>Confidence Threshold</strong></td><td>Minimum confidence score (default <strong>0.7 — Balanced</strong>) required before a proposed change is applied without review. Below the threshold, the change is held in the Approval Queue regardless of the approval mode.</td></tr><tr><td><strong>Change Approval Mode</strong></td><td><em>Auto-apply</em> / <em>Confirm &amp; apply</em> / <em>Manual review</em>. Governs how AI-proposed changes land in your data. Defaults to <em>&quot;Confirm &amp; apply (propose values, ask to confirm, then execute)&quot;</em>.</td></tr></tbody></table>',4)),n(o,{src:"/assets/2.1/images/magic-ai/magic-ai-settings.png",alt:"Magic AI Settings — Agentic PIM section"}),t[2]||(t[2]=e('<h2 id="recommended-setup-sequence" tabindex="-1">Recommended setup sequence <a class="header-anchor" href="#recommended-setup-sequence" aria-label="Permalink to &quot;Recommended setup sequence&quot;">​</a></h2><p>Agentic PIM has a lot of knobs. A typical rollout looks like this:</p><ol><li><strong>Day 0 — cautious start.</strong> Enable AI Agent Chat only. Set <em>Max Agent Steps Per Turn</em> to the lowest preset, Daily Token Budget to a conservative number, and Change Approval Mode to <strong>Manual review</strong>.</li><li><strong>Day 1-3 — observe in Analytics.</strong> Watch token usage and which tools the agent actually calls. Review every change in the Approval Queue.</li><li><strong>Day 4+ — loosen selectively.</strong> Raise the token budget once you understand the spend. Move trusted workflows (e.g., filling meta descriptions in a specific family) to <strong>Confirm &amp; apply</strong> or <strong>Auto-apply</strong>. Leave risky workflows in Manual review.</li><li><strong>Week 2 — turn on background workers.</strong> Enable <strong>Auto-Enrichment on Product Create</strong> first (single-entity, predictable cost). Enable <strong>Catalog Quality Monitor</strong> once you&#39;re happy with enrichment quality.</li></ol><h2 id="how-agentic-pim-relates-to-other-docs" tabindex="-1">How Agentic PIM relates to other docs <a class="header-anchor" href="#how-agentic-pim-relates-to-other-docs" aria-label="Permalink to &quot;How Agentic PIM relates to other docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If you want to…</th><th>Read</th></tr></thead><tbody><tr><td>Learn the chat UI in detail</td><td><strong><a href="./../ai-agent/ai-agent-chat.html">AI Agent Chat</a></strong></td></tr><tr><td>Review, approve, or reject proposed changes</td><td><strong><a href="./../ai-agent/approval-queue.html">Approval Queue</a></strong></td></tr><tr><td>See token usage, costs, and activity</td><td><strong><a href="./../ai-agent/analytics.html">Analytics</a></strong></td></tr><tr><td>Configure Platforms, Prompts, System Prompts</td><td><strong><a href="./../configuration/magic-ai.html">Magic AI Configuration</a></strong></td></tr><tr><td>Fine-tune per-capability routing (Text / Image / Translation)</td><td><strong><a href="./../magic-ai/settings.html">Magic AI → Settings</a></strong></td></tr></tbody></table><h2 id="safety-controls-at-a-glance" tabindex="-1">Safety controls at a glance <a class="header-anchor" href="#safety-controls-at-a-glance" aria-label="Permalink to &quot;Safety controls at a glance&quot;">​</a></h2><p>Four layers stack up to keep Agentic PIM&#39;s autonomy in check:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Configured at</th><th>What it protects</th></tr></thead><tbody><tr><td><strong>ACL permissions</strong></td><td>Settings → Roles</td><td>Stops the agent from doing anything the caller&#39;s role can&#39;t do.</td></tr><tr><td><strong>Daily Token Budget</strong></td><td>Magic AI → Settings → Agentic PIM</td><td>Caps total spend across all Agentic PIM workers per day.</td></tr><tr><td><strong>Max Agent Steps Per Turn</strong></td><td>Magic AI → Settings → Agentic PIM</td><td>Caps how many tools one trigger can chain.</td></tr><tr><td><strong>Confidence Threshold + Change Approval Mode + Approval Queue</strong></td><td>Magic AI → Settings → Agentic PIM</td><td>Holds risky or low-confidence writes for review.</td></tr></tbody></table><p>None of these require re-deploying or restarting — save the Magic AI settings page and every Agentic PIM worker picks up the new values on its next run.</p>',9))])}const f=a(d,[["render",g]]);export{A as __pageData,f as default};
